`timescale 1ns / 1ps

module tb_md5_long_message;

    reg clk;
    reg reset;
    reg [511:0] chunk;
    wire [31:0] a64, b64, c64, d64;

    Md5Core u_md5 (
        .clk(clk),
        .wb(chunk),
        .a0(32'h67452301),
        .b0(32'hefcdab89),
        .c0(32'h98badcfe),
        .d0(32'h10325476),
        .a64(a64),
        .b64(b64),
        .c64(c64),
        .d64(d64)
    );

    initial clk = 0;
    always #5 clk = ~clk;

    integer i;
    reg [511:0] messages [0:9];

    initial begin
        // 预定义10个不同的512位块，模拟长消息
        messages[0] = 512';
        messages[1] = 512';
        // ... 可以填入更多块，为了简洁，这里只定义两个，实际可重复使用
        for (i = 2; i < 10; i = i + 1)
            messages[i] = messages[i-1] ^ 512'hFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF;
    end

    initial begin
        $dumpfile("md5_long_message.vcd");
        $dumpvars(0, tb_md5_long_message);

        reset = 1;
        chunk = 512'b0;
        #20;
        reset = 0;
        #10;

        // 发送10个块
        for (i = 0; i < 10; i = i + 1) begin
            chunk = messages[i];
            #650;
        end

        #1000;
        $finish;
    end

endmodule